142	    bind.dnsutils
143	    openssl
144	    dnsdist
145	    nsd
146	    pdns-recursor
147	  ];
148	
149	  # ---- Authoritative: NSD on 127.0.0.1:5301 -------------------------------
150	  services.nsd = {
151	    enable = true;
152	    interfaces = [ "127.0.0.1@5301" ];
153	    ipv4 = true;
154	    ipv6 = false;
155	    hideVersion = true;
156	    identity = "node23-auth";
157	    verbosity = 0;
158	    remoteControl.enable = false;
159	    zones = {
160	      "a23.test" = {
161	        data = builtins.readFile ./zones/a23.test.zone;
162	        provideXFR = [ "198.51.100.7 NOKEY" ];
163	      };
164	      "2.0.192.in-addr.arpa" = {
165	        data = builtins.readFile ./zones/192.0.2.rev.zone;
166	      };
167	    };
168	  };
169	
170	  # ---- Recursor: PowerDNS Recursor on 127.0.0.1:5353 ----------------------
171	  services.pdns-recursor = {
172	    enable = true;
173	    dns.address = [ "127.0.0.1" ];
174	    dns.port = 5353;
175	    dns.allowFrom = [ "127.0.0.0/8" ];
176	    api.address = "127.0.0.1";
177	    api.port = 8082;
178	    api.allowFrom = [ "127.0.0.1" ];
179	    dnssecValidation = "off";
180	    exportHosts = true;
181	    forwardZones = {
182	      "a23.test" = "127.0.0.1:5301";
183	      "2.0.192.in-addr.arpa" = "127.0.0.1:5301";
184	    };
185	    settings = {
186	      recursor = {
187	        threads = 4;
188	        qname_minimization = false;
189	        version_string = "anonymous";
190	        etc_hosts_file = "${recursorHosts}";
191	        auth_zones = [
192	          {
193	            zone = "i23.test";
194	            file = "${./powerdns/i23.test.zone}";
195	          }
196	        ];
197	      };
198	      recordcache = {
199	        max_entries = 1000000;
200	        max_ttl = 3600;
201	        max_negative_ttl = 1800;
202	      };
203	      incoming = {
204	        reuseport = true;
205	        max_tcp_clients = 128;
206	        max_tcp_per_client = 100;
207	        tcp_timeout = 2;
208	      };
209	      webservice = {
210	        webserver = true;
211	        api_key = "lab-api-key";
212	      };
213	      logging.quiet = true;
214	    };
215	  };
216	
217	  systemd.services.pdns-recursor.serviceConfig = {
218	    User = lib.mkForce "pdns";
219	    Group = lib.mkForce "pdns";
220	  };
221	
222	  # ---- Load balancer / policy: dnsdist on 0.0.0.0:53 and :853 -------------
223	  systemd.services.dnsdist = {
224	    description = "DNS Loadbalancer";
225	    documentation = [ "man:dnsdist(1)" "https://dnsdist.org" ];
226	    wantedBy = [ "multi-user.target" ];
227	    wants = [ "network-online.target" ];
228	    after = [ "network-online.target" ];
229	    serviceConfig = {
230	      Type = "notify";
231	      ExecStartPre = "${pkgs.dnsdist}/bin/dnsdist --check-config --config ${dnsdistConf}";
232	      ExecStart = "${pkgs.dnsdist}/bin/dnsdist --supervised --disable-syslog --config ${dnsdistConf}";
233	      User = "_dnsdist";
234	      Group = "_dnsdist";
235	      Restart = "on-failure";
236	      RestartSec = 2;
237	      TimeoutStopSec = 5;
238	      StartLimitIntervalSec = 0;
239	      LimitNOFILE = 65536;
240	      TasksMax = 8192;
241	      CapabilityBoundingSet = [ "CAP_NET_BIND_SERVICE" ];
242	      AmbientCapabilities = [ "CAP_NET_BIND_SERVICE" ];
243	      NoNewPrivileges = true;
244	      PrivateDevices = true;
245	    };
246	  };
247	}
